using System;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Collections.Generic;
class SubtitleConfirmChecks{static IEnumerable<Control> Children(Control c){foreach(Control x in c.Controls){yield return x;foreach(var y in Children(x))yield return y;}}[STAThread]static void Main(){Application.EnableVisualStyles();using(var g=new Game()){var f=BindingFlags.Instance|BindingFlags.NonPublic;var save=new Save();var chapter=((List<Chapter>)typeof(Game).GetField("chapters",f).GetValue(g)).First(WaystationChapterOne.Is);typeof(Game).GetField("save",f).SetValue(g,save);typeof(Game).GetField("current",f).SetValue(g,chapter);typeof(Game).GetField("page",f).SetValue(g,"waystation-chapter-cg");typeof(Game).GetField("translating",f).SetValue(g,false);typeof(Game).GetField("englishVisible",f).SetValue(g,false);save.chinese=save.english=false;var attempt=(SectionAttempt)typeof(Game).GetMethod("Attempt",f).Invoke(g,null);attempt.subtitlesChosen=true;var method=typeof(Game).GetMethod("SetStorySubtitle",f);foreach(var confirm in new[]{false,true})using(var timer=new Timer{Interval=30}){timer.Tick+=(s,e)=>{var dialog=Application.OpenForms.Cast<Form>().FirstOrDefault(x=>x.Text=="开启字幕确认");if(dialog==null)return;timer.Stop();Children(dialog).OfType<Button>().First(x=>x.Text==(confirm?"确认":"取消")).PerformClick();};timer.Start();bool accepted=(bool)method.Invoke(g,new object[]{true,true});if(accepted!=confirm||save.chinese!=confirm||attempt.usedChineseSubtitles!=confirm)throw new Exception("subtitle confirmation state mismatch");}if(SectionRules.Stars(1,1,attempt.usedChineseSubtitles,attempt.usedEnglishSubtitles)!=1)throw new Exception("star reduction missing");}Console.WriteLine("PASS cancel preserves mode/rating; confirmation enables Chinese and records one-star ceiling");}}
